1	<script lang="ts">
2		import { createEventDispatcher, onMount } from "svelte";
3		import type { SelectData } from "@gradio/utils";
4		import { uploadToHuggingFace } from "@gradio/utils";
5		import {
6			BlockLabel,
7			Empty,
8			IconButton,
9			ShareButton,
10			IconButtonWrapper,
11			FullscreenButton,
12			DownloadLink
13		} from "@gradio/atoms";
14		import type { CustomButton as CustomButtonType } from "@gradio/utils";
15		import { Download, Image as ImageIcon } from "@gradio/icons";
16		import { get_coordinates_of_clicked_image } from "./utils";
17		import Image from "./Image.svelte";
18	
19		import type { I18nFormatter } from "@gradio/utils";
20		import type { FileData } from "@gradio/client";
21	
22		export let value: null | FileData;
23		export let label: string | undefined = undefined;
24		export let show_label: boolean;
25		export let buttons: (string | CustomButtonType)[] = [];
26		export let on_custom_button_click: ((id: number) => void) | null = null;
27		export let selectable = false;
28		export let i18n: I18nFormatter;
29		export let display_icon_button_wrapper_top_corner = false;
30		export let fullscreen = false;
31		export let show_button_background = true;
32	
33		const dispatch = createEventDispatcher<{
34			change: string;
35			select: SelectData;
36			fullscreen: boolean;
37		}>();
38	
39		const handle_click = (evt: MouseEvent): void => {
40			let coordinates = get_coordinates_of_clicked_image(evt);
41			if (coordinates) {
42				dispatch("select", { index: coordinates, value: null });
43			}
44		};
45	
46		let image_container: HTMLElement;
47	</script>
48	
49	<BlockLabel
50		{show_label}
51		Icon={ImageIcon}
52		label={!show_label ? "" : label || i18n("image.image")}
53	/>
54	{#if value == null || !value?.url}
55		<Empty unpadded_box={true} size="large"><ImageIcon /></Empty>
56	{:else}
57		<div class="image-container" bind:this={image_container}>
58			<IconButtonWrapper
59				display_top_corner={display_icon_button_wrapper_top_corner}
60				show_background={show_button_background}
61				{buttons}
62				{on_custom_button_click}
63			>
64				{#if buttons.some((btn) => typeof btn === "string" && btn === "fullscreen")}
65					<FullscreenButton
66						{fullscreen}
67						onclick={(is_fullscreen) => {
68							fullscreen = is_fullscreen;
69							dispatch("fullscreen", is_fullscreen);
70						}}
71					/>
72				{/if}
73				{#if buttons.some((btn) => typeof btn === "string" && btn === "download")}
74					<DownloadLink href={value.url} download={value.orig_name || "image"}>
75						<IconButton Icon={Download} label={i18n("common.download")} />
76					</DownloadLink>
77				{/if}
78				{#if buttons.some((btn) => typeof btn === "string" && btn === "share")}
79					<ShareButton
80						{i18n}
81						on:share
82						on:error
83						formatter={async (value) => {
84							if (!value) return "";
85							let url = await uploadToHuggingFace(value, "url");
86							return `<img src="${url}" />`;
87						}}
88						{value}
89					/>
90				{/if}
91			</IconButtonWrapper>
92			<button on:click={handle_click}>
93				<div class:selectable class="image-frame">
94					<Image
95						src={value.url}
96						restProps={{ loading: "lazy", alt: "" }}
97						on:load
98					/>
99				</div>
100			</button>
101		</div>
102	{/if}
